import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { orderAPI, productAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

const STATUS_OPTIONS = ['Pending', 'Confirmed', 'Out for Delivery', 'Delivered', 'Cancelled'];
const STATUS_COLORS = { 'Pending': '#f59e0b', 'Confirmed': '#3b82f6', 'Out for Delivery': '#8b5cf6', 'Delivered': '#16a34a', 'Cancelled': '#dc2626' };
const CATEGORIES = ['meat-fish', 'vegetables', 'dairy-eggs', 'oils-ghee', 'millets-groceries', 'dry-fruits', 'masalas', 'chocolates'];

const AdminDashboard = () => {
  const { user, isAdmin } = useAuth();
  const navigate = useNavigate();
  const [tab, setTab] = useState('dashboard');
  const [analytics, setAnalytics] = useState(null);
  const [orders, setOrders] = useState([]);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('');
  const [productModal, setProductModal] = useState(null);
  const [productForm, setProductForm] = useState({ name: '', description: '', price: '', category: 'vegetables', unit: '', stock: 100, inStock: true, featured: false, originalPrice: '' });
  const [imageFile, setImageFile] = useState(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!user || !isAdmin) { navigate('/login'); return; }
    loadAll();
  }, [user, isAdmin]);

  const loadAll = async () => {
    setLoading(true);
    try {
      const [aRes, oRes, pRes] = await Promise.all([orderAPI.getAnalytics(), orderAPI.getAllOrders({ limit: 200 }), productAPI.getAll({ limit: 200 })]);
      setAnalytics(aRes.data.analytics);
      setOrders(oRes.data.orders);
      setProducts(pRes.data.products);
    } catch (e) { toast.error('Failed to load data'); }
    setLoading(false);
  };

  const handleStatusChange = async (orderId, status) => {
    try {
      await orderAPI.updateStatus(orderId, status);
      setOrders(prev => prev.map(o => o._id === orderId ? { ...o, status } : o));
      toast.success(`Order status updated to ${status}`);
    } catch { toast.error('Failed to update status'); }
  };

  const handleDeleteOrder = async (id) => {
    if (!window.confirm('Delete this order?')) return;
    try {
      await orderAPI.deleteOrder(id);
      setOrders(prev => prev.filter(o => o._id !== id));
      toast.success('Order deleted');
    } catch { toast.error('Failed to delete order'); }
  };

  const handleExportCSV = async () => {
    try {
      const res = await orderAPI.exportCSV();
      const url = URL.createObjectURL(res.data);
      const a = document.createElement('a');
      a.href = url; a.download = 'desi2door-orders.csv'; a.click();
      URL.revokeObjectURL(url);
    } catch { toast.error('Export failed'); }
  };

  const openProductModal = (product = null) => {
    if (product) {
      setProductForm({ name: product.name, description: product.description || '', price: product.price, category: product.category, unit: product.unit || '', stock: product.stock || 100, inStock: product.inStock !== false, featured: product.featured || false, originalPrice: product.originalPrice || '' });
      setProductModal(product._id);
    } else {
      setProductForm({ name: '', description: '', price: '', category: 'vegetables', unit: '', stock: 100, inStock: true, featured: false, originalPrice: '' });
      setProductModal('new');
    }
    setImageFile(null);
  };

  const saveProduct = async () => {
    if (!productForm.name || !productForm.price || !productForm.category) { toast.error('Fill required fields'); return; }
    setSaving(true);
    try {
      const fd = new FormData();
      Object.entries(productForm).forEach(([k, v]) => fd.append(k, v));
      if (imageFile) fd.append('image', imageFile);
      if (productModal === 'new') {
        const res = await productAPI.create(fd);
        setProducts(prev => [res.data.product, ...prev]);
        toast.success('Product added!');
      } else {
        const res = await productAPI.update(productModal, fd);
        setProducts(prev => prev.map(p => p._id === productModal ? res.data.product : p));
        toast.success('Product updated!');
      }
      setProductModal(null);
    } catch (e) { toast.error('Failed to save product'); }
    setSaving(false);
  };

  const deleteProduct = async (id) => {
    if (!window.confirm('Delete this product?')) return;
    try {
      await productAPI.delete(id);
      setProducts(prev => prev.filter(p => p._id !== id));
      toast.success('Product deleted');
    } catch { toast.error('Failed to delete'); }
  };

  const filteredOrders = statusFilter ? orders.filter(o => o.status === statusFilter) : orders;

  if (loading) return <div className="spinner" style={{ marginTop: 100 }} />;

  const TabBtn = ({ id, icon, label }) => (
    <button onClick={() => setTab(id)} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 16px', borderRadius: 10, border: 'none', cursor: 'pointer', fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 14, transition: 'all 0.15s', background: tab === id ? 'var(--green)' : 'transparent', color: tab === id ? 'white' : '#6b7280' }}>
      <span>{icon}</span> {label}
    </button>
  );

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: 'var(--gray-50)' }}>
      {/* Sidebar */}
      <div style={{ width: 220, background: 'white', borderRight: '1px solid var(--gray-100)', padding: '20px 12px', display: 'flex', flexDirection: 'column', gap: 4, flexShrink: 0 }}>
        <div style={{ padding: '8px 12px', marginBottom: 16 }}>
          <div style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 800, color: 'var(--green)' }}>🌿 Desi2Door</div>
          <div style={{ fontSize: 12, color: 'var(--gray-400)', fontWeight: 600 }}>Admin Panel</div>
        </div>
        <TabBtn id="dashboard" icon="📊" label="Dashboard" />
        <TabBtn id="orders" icon="📦" label="Orders" />
        <TabBtn id="products" icon="🛒" label="Products" />
        <div style={{ marginTop: 'auto', padding: '12px', fontSize: 13, color: 'var(--gray-400)', borderTop: '1px solid var(--gray-100)' }}>
          👤 {user?.name}
        </div>
      </div>

      {/* Main Content */}
      <div style={{ flex: 1, overflow: 'auto' }}>
        <div style={{ padding: '24px' }}>

          {/* DASHBOARD TAB */}
          {tab === 'dashboard' && analytics && (
            <div>
              <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28, marginBottom: 24 }}>📊 Dashboard</h1>
              {/* Stats */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 16, marginBottom: 28 }}>
                {[
                  { icon: '📦', label: "Today's Sales", value: `₹${analytics.todaySales}`, color: 'var(--green)' },
                  { icon: '💰', label: 'Total Sales', value: `₹${analytics.totalSales}`, color: 'var(--orange)' },
                  { icon: '🛒', label: 'Total Orders', value: analytics.totalOrders, color: '#3b82f6' },
                  { icon: '⏳', label: 'Pending', value: analytics.pendingOrders, color: '#f59e0b' },
                  { icon: '✅', label: 'Delivered', value: analytics.deliveredOrders, color: '#16a34a' },
                ].map(stat => (
                  <div key={stat.label} style={{ background: 'white', borderRadius: 16, padding: '20px', boxShadow: '0 2px 8px rgba(0,0,0,0.06)', borderLeft: `4px solid ${stat.color}` }}>
                    <div style={{ fontSize: 28 }}>{stat.icon}</div>
                    <div style={{ fontFamily: 'var(--font-display)', fontSize: 26, fontWeight: 800, color: stat.color, marginTop: 6 }}>{stat.value}</div>
                    <div style={{ fontSize: 13, color: 'var(--gray-400)', fontWeight: 600 }}>{stat.label}</div>
                  </div>
                ))}
              </div>
              {/* Last 7 Days */}
              <div style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 2px 8px rgba(0,0,0,0.06)', marginBottom: 20 }}>
                <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, marginBottom: 16 }}>📈 Last 7 Days Sales</h3>
                <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', height: 120, overflowX: 'auto' }}>
                  {analytics.last7Days.map(day => {
                    const maxSales = Math.max(...analytics.last7Days.map(d => d.sales), 1);
                    const h = Math.max((day.sales / maxSales) * 100, 4);
                    return (
                      <div key={day.date} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, flex: 1, minWidth: 60 }}>
                        <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--green)' }}>₹{day.sales}</div>
                        <div style={{ background: 'var(--green)', borderRadius: '6px 6px 0 0', width: '100%', height: `${h}px`, minHeight: 4, transition: 'height 0.5s' }} />
                        <div style={{ fontSize: 11, color: 'var(--gray-400)', fontWeight: 600 }}>{day.date}</div>
                        <div style={{ fontSize: 10, color: 'var(--gray-300)' }}>{day.count} orders</div>
                      </div>
                    );
                  })}
                </div>
              </div>
              {/* Recent Orders */}
              <div style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, marginBottom: 16 }}>🕐 Recent Orders</h3>
                {analytics.recentOrders?.map(order => (
                  <div key={order._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid var(--gray-100)', flexWrap: 'wrap', gap: 8 }}>
                    <div>
                      <div style={{ fontWeight: 700, fontSize: 14 }}>{order.customerName} — {order.invoiceNumber}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-400)' }}>{new Date(order.createdAt).toLocaleDateString('en-IN')}</div>
                    </div>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      <span style={{ background: STATUS_COLORS[order.status] + '20', color: STATUS_COLORS[order.status], fontWeight: 700, fontSize: 12, padding: '3px 10px', borderRadius: 20 }}>{order.status}</span>
                      <span style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--green)' }}>₹{order.totalAmount}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ORDERS TAB */}
          {tab === 'orders' && (
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20, flexWrap: 'wrap', gap: 12 }}>
                <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28 }}>📦 Orders ({filteredOrders.length})</h1>
                <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                  <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} style={{ padding: '10px 14px', borderRadius: 10, border: '2px solid var(--gray-200)', fontWeight: 600, width: 'auto' }}>
                    <option value="">All Status</option>
                    {STATUS_OPTIONS.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <button onClick={handleExportCSV} className="btn-outline" style={{ padding: '10px 16px', fontSize: 14 }}>📥 Export CSV</button>
                </div>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                {filteredOrders.map(order => (
                  <div key={order._id} style={{ background: 'white', borderRadius: 16, padding: 20, boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 12, marginBottom: 12 }}>
                      <div>
                        <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 16 }}>{order.customerName}</div>
                        <div style={{ fontSize: 13, color: 'var(--gray-400)' }}>📱 {order.customerPhone} | 🎫 {order.invoiceNumber}</div>
                        <div style={{ fontSize: 13, color: 'var(--gray-400)' }}>📍 {order.address.street}, {order.address.city} — ⏰ {order.deliverySlot || 'N/A'}</div>
                        <div style={{ fontSize: 12, color: 'var(--gray-300)', marginTop: 2 }}>{new Date(order.createdAt).toLocaleString('en-IN')}</div>
                      </div>
                      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 8 }}>
                        <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 20, color: 'var(--green)' }}>₹{order.totalAmount}</div>
                        <select value={order.status} onChange={e => handleStatusChange(order._id, e.target.value)}
                          style={{ background: STATUS_COLORS[order.status] + '20', color: STATUS_COLORS[order.status], border: 'none', borderRadius: 8, padding: '6px 12px', fontWeight: 700, fontSize: 13, cursor: 'pointer', width: 'auto' }}>
                          {STATUS_OPTIONS.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                        <button onClick={() => handleDeleteOrder(order._id)} style={{ background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: 8, padding: '6px 12px', fontSize: 12, cursor: 'pointer', fontWeight: 600 }}>
                          🗑 Delete
                        </button>
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', borderTop: '1px solid var(--gray-100)', paddingTop: 10 }}>
                      {order.items.map((item, i) => (
                        <span key={i} style={{ background: 'var(--gray-50)', border: '1px solid var(--gray-200)', borderRadius: 8, padding: '3px 10px', fontSize: 12 }}>
                          {item.name} ×{item.quantity}
                        </span>
                      ))}
                    </div>
                  </div>
                ))}
                {filteredOrders.length === 0 && (
                  <div style={{ textAlign: 'center', padding: 60, color: 'var(--gray-400)', fontSize: 16 }}>
                    📭 No orders found
                  </div>
                )}
              </div>
            </div>
          )}

          {/* PRODUCTS TAB */}
          {tab === 'products' && (
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20, flexWrap: 'wrap', gap: 12 }}>
                <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28 }}>🛒 Products ({products.length})</h1>
                <button onClick={() => openProductModal()} className="btn-primary">+ Add Product</button>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 14 }}>
                {products.map(product => (
                  <div key={product._id} style={{ background: 'white', borderRadius: 16, overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                    <div style={{ height: 120, background: 'var(--gray-50)', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative', overflow: 'hidden' }}>
                      {product.image ? <img src={product.image} alt={product.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <span style={{ fontSize: 50 }}>🛒</span>}
                      {!product.inStock && <span className="badge-out" style={{ position: 'absolute', top: 8, left: 8 }}>Out of Stock</span>}
                      {product.featured && <span style={{ position: 'absolute', top: 8, right: 8, background: 'var(--orange)', color: 'white', fontSize: 11, padding: '2px 8px', borderRadius: 20, fontWeight: 700 }}>Featured</span>}
                    </div>
                    <div style={{ padding: '14px' }}>
                      <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 15, marginBottom: 4 }}>{product.name}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-400)', marginBottom: 8 }}>{product.category} | {product.unit}</div>
                      <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 20, color: 'var(--green)', marginBottom: 12 }}>₹{product.price}</div>
                      <div style={{ display: 'flex', gap: 8 }}>
                        <button onClick={() => openProductModal(product)} style={{ flex: 1, background: 'var(--green-bg)', color: 'var(--green-dark)', border: 'none', borderRadius: 8, padding: '8px', fontSize: 13, fontWeight: 700, cursor: 'pointer' }}>
                          ✏️ Edit
                        </button>
                        <button onClick={() => deleteProduct(product._id)} style={{ background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: 8, padding: '8px 12px', fontSize: 13, cursor: 'pointer', fontWeight: 600 }}>
                          🗑
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Product Modal */}
      {productModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 200, padding: 16 }}>
          <div style={{ background: 'white', borderRadius: 20, padding: 28, width: '100%', maxWidth: 500, maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 20px 60px rgba(0,0,0,0.2)' }}>
            <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 22, marginBottom: 20 }}>
              {productModal === 'new' ? '➕ Add New Product' : '✏️ Edit Product'}
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              {[['Product Name *', 'name', 'text'], ['Description', 'description', 'text'], ['Unit (e.g. 500g, 1kg)', 'unit', 'text']].map(([label, key, type]) => (
                <div key={key}>
                  <label style={{ fontWeight: 600, fontSize: 14, display: 'block', marginBottom: 6 }}>{label}</label>
                  <input type={type} value={productForm[key]} onChange={e => setProductForm(f => ({ ...f, [key]: e.target.value }))} />
                </div>
              ))}
              <div style={{ display: 'flex', gap: 12 }}>
                <div style={{ flex: 1 }}>
                  <label style={{ fontWeight: 600, fontSize: 14, display: 'block', marginBottom: 6 }}>Price (₹) *</label>
                  <input type="number" value={productForm.price} onChange={e => setProductForm(f => ({ ...f, price: e.target.value }))} />
                </div>
                <div style={{ flex: 1 }}>
                  <label style={{ fontWeight: 600, fontSize: 14, display: 'block', marginBottom: 6 }}>Original Price</label>
                  <input type="number" value={productForm.originalPrice} onChange={e => setProductForm(f => ({ ...f, originalPrice: e.target.value }))} placeholder="For strikethrough" />
                </div>
              </div>
              <div>
                <label style={{ fontWeight: 600, fontSize: 14, display: 'block', marginBottom: 6 }}>Category *</label>
                <select value={productForm.category} onChange={e => setProductForm(f => ({ ...f, category: e.target.value }))} style={{ width: '100%' }}>
                  {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label style={{ fontWeight: 600, fontSize: 14, display: 'block', marginBottom: 6 }}>Stock Quantity</label>
                <input type="number" value={productForm.stock} onChange={e => setProductForm(f => ({ ...f, stock: e.target.value }))} />
              </div>
              <div style={{ display: 'flex', gap: 16 }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', fontWeight: 600 }}>
                  <input type="checkbox" checked={productForm.inStock} onChange={e => setProductForm(f => ({ ...f, inStock: e.target.checked }))} style={{ width: 18, height: 18 }} />
                  In Stock
                </label>
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', fontWeight: 600 }}>
                  <input type="checkbox" checked={productForm.featured} onChange={e => setProductForm(f => ({ ...f, featured: e.target.checked }))} style={{ width: 18, height: 18 }} />
                  Featured
                </label>
              </div>
              <div>
                <label style={{ fontWeight: 600, fontSize: 14, display: 'block', marginBottom: 6 }}>Product Image</label>
                <input type="file" accept="image/*" onChange={e => setImageFile(e.target.files[0])} style={{ border: '2px dashed var(--gray-200)', padding: '12px', borderRadius: 8 }} />
              </div>
              <div style={{ display: 'flex', gap: 12, marginTop: 8 }}>
                <button onClick={saveProduct} disabled={saving} className="btn-primary" style={{ flex: 1, justifyContent: 'center', opacity: saving ? 0.7 : 1 }}>
                  {saving ? '⏳ Saving...' : '💾 Save Product'}
                </button>
                <button onClick={() => setProductModal(null)} className="btn-outline" style={{ flex: 1, justifyContent: 'center' }}>Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
